class Solution:
    def minAbsoluteSumDiff(self, nums1: List[int], nums2: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums1)
        total = sum(abs(nums1[i] - nums2[i]) for i in range(n))
        best = 0
        for i in range(n):
            for v in nums1:
                best = max(best, abs(nums1[i] - nums2[i]) - abs(v - nums2[i]))
        return (total - best) % MOD

