class Solution {
    public int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
        final int MOD = 1_000_000_007;
        int n = nums1.length;
        int[] sorted1 = nums1.clone();
        Arrays.sort(sorted1);
        long total = 0, best = 0;
        for (int i = 0; i < n; i++) {
            int cur = Math.abs(nums1[i] - nums2[i]);
            total += cur;
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (sorted1[mid] < nums2[i]) lo = mid + 1; else hi = mid;
            }
            int cand = Integer.MAX_VALUE;
            if (lo < n) cand = Math.min(cand, Math.abs(sorted1[lo] - nums2[i]));
            if (lo > 0) cand = Math.min(cand, Math.abs(sorted1[lo - 1] - nums2[i]));
            best = Math.max(best, cur - cand);
        }
        return (int)((total - best) % MOD);
    }
}

